WITH base AS (SELECT *, INITCAP(TRIM(city)) AS city_title, COALESCE(region, 'DIRECT') AS region_filled FROM stores WHERE opened_date > TO_DATE('2023-05-10')), enriched AS (SELECT id, opened_date, sqft, region_filled, LEAD(sqft) OVER (PARTITION BY region, city ORDER BY opened_date ASC, id ASC) AS next_sqft, ROW_NUMBER() OVER (PARTITION BY region, city ORDER BY opened_date ASC, id ASC) AS row_seq FROM base), with_latest AS (SELECT s.*, top1.revenue FROM enriched s LEFT JOIN LATERAL (SELECT c.revenue FROM store_sales c WHERE c.store_id = s.id AND c.sale_date <= s.opened_date ORDER BY c.sale_date DESC, c.id DESC LIMIT 1) top1 ON TRUE), enriched_stores AS (SELECT *, MAX(next_sqft) OVER (ORDER BY revenue ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_next_sqft, MIN(next_sqft) OVER (ORDER BY revenue ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_next_sqft, SUM(next_sqft) OVER (ORDER BY revenue ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_next_sqft, LAST_VALUE(next_sqft) IGNORE NULLS OVER (ORDER BY sqft ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_next_sqft FROM with_latest WHERE revenue < 3400) SELECT id, opened_date, sqft, region_filled, next_sqft, row_seq, revenue, running_max_next_sqft, running_min_next_sqft FROM enriched_stores ORDER BY revenue DESC;
